// Intuit signs the raw body with HMAC-SHA256 using the app's Webhooks Verifier Token
// (Intuit Developer Dashboard → Webhooks). Header: intuit-signature, base64 digest.
const crypto = require('crypto');

const item = $input.first();
const verifier = $vars.INTUIT_VERIFIER_TOKEN; // n8n Variables, or replace with a literal
if (!verifier) throw new Error('INTUIT_VERIFIER_TOKEN is not configured');

const rawBody = item.binary && item.binary.data
  ? Buffer.from(item.binary.data.data, 'base64')
  : Buffer.from(JSON.stringify(item.json.body || {}), 'utf8');

const headers = item.json.headers || {};
const provided = headers['intuit-signature'] || headers['Intuit-Signature'] || '';
const expected = crypto.createHmac('sha256', verifier).update(rawBody).digest('base64');

const a = Buffer.from(String(provided));
const b = Buffer.from(expected);
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) {
  throw new Error('Invalid intuit-signature — dropping event');
}

return [{ json: JSON.parse(rawBody.toString('utf8')) }];

// Flatten eventNotifications[].dataChangeEvent.entities[] and keep Payment entities only.
const out = [];
for (const item of $input.all()) {
  const notifications = item.json.eventNotifications || [];
  for (const n of notifications) {
    const entities = (n.dataChangeEvent && n.dataChangeEvent.entities) || [];
    for (const e of entities) {
      if (e.name !== 'Payment') continue;
      out.push({
        json: {
          realmId: n.realmId,
          id: String(e.id),
          operation: e.operation, // Create | Update | Delete | Merge | Void
          lastUpdated: e.lastUpdated,
          deletedId: e.deletedId ? String(e.deletedId) : null, // Merge only: the id folded into `id`
        },
      });
    }
  }
}
return out;

// Deleted entities can't be fetched from QBO; forward the id only.
return $input.all().map(item => ({
  json: {
    qbo_payment_id: item.json.id,
    event_type: 'Delete',
    deleted: true,
    realm_id: item.json.realmId,
    last_updated: item.json.lastUpdated,
  },
}));

// Normalize the QBO Payment object into the ERPNext payload (runs once per item;
// paired-item lookup gives us the originating webhook entity).
const payment = $input.item.json.Payment || $input.item.json;
const source = $('Split Payment Entities').item.json;

const invoiceIds = [];
for (const line of payment.Line || []) {
  for (const lt of line.LinkedTxn || []) {
    if (lt.TxnType === 'Invoice' && lt.TxnId) invoiceIds.push(String(lt.TxnId));
  }
}

let eventType = source.operation || 'Update';
if (eventType === 'Void') eventType = 'Delete';

return {
  json: {
    qbo_payment_id: String(payment.Id),
    event_type: eventType,
    amount: Number(payment.TotalAmt || 0),
    txn_date: payment.TxnDate || null,
    qbo_invoice_id: invoiceIds[0] || null,
    qbo_invoice_ids: invoiceIds,
    customer_qbo_id: payment.CustomerRef ? String(payment.CustomerRef.value) : null,
    merged_from_id: source.deletedId || null,
    deleted: false,
    realm_id: source.realmId || null,
    last_updated: source.lastUpdated || (payment.MetaData && payment.MetaData.LastUpdatedTime) || null,
  },
};

// Sign the exact JSON string that will be sent. ERPNext recomputes
// HMAC-SHA256(raw_body, qbo_webhook_secret) and compares hex digests.
const crypto = require('crypto');
const secret = $vars.QBO_WEBHOOK_SECRET; // same value as ilL-QBO-Settings.webhook_secret
if (!secret) throw new Error('QBO_WEBHOOK_SECRET is not configured');

return $input.all().map(item => {
  const body = JSON.stringify(item.json);
  const signature = crypto.createHmac('sha256', secret).update(body, 'utf8').digest('hex');
  return { json: { body, signature, qbo_payment_id: item.json.qbo_payment_id, event_type: item.json.event_type } };
});

// Shape an alert message. Replace the downstream NoOp with a Slack / Email node.
return $input.all().map(item => {
  const r = item.json.message || item.json;
  return {
    json: {
      subject: `QBO → ERPNext payment sync failed: ${r.error || 'unknown'}`,
      text: [
        `Error: ${r.error || 'unknown'}`,
        `Detail: ${r.message || ''}`,
        `Sync log: ${r.log || 'n/a'} (open ilL-QBO-Sync-Log in ERPNext)`,
        `Payload: ${$('Sign Request (HMAC)').item.json.body}`,
      ].join('\n'),
      raw: item.json,
    },
  };
});
